svg.script:

(function () {
  var svgNS = 'http://www.w3.org/2000/svg';
  var svg = document.currentScript && document.currentScript.ownerSVGElement;
  var toolbar = (svg || document).querySelector('[data-name="zuoce-gongnneg"]');
  if (!toolbar) return;

  var selectedStyle = toolbar.querySelector('[data-name="xaunzhongyangshi"]');
  var firstTool = toolbar.querySelector('[data-name="yidongvgongjv"]');
  var toolInsertPoint = toolbar.querySelector('[data-name="jvxingxuankuanggongjv"]') || firstTool;
  if (!selectedStyle || !firstTool) return;

  selectedStyle.classList.add('ps-tool-selection-style');
  toolbar.insertBefore(selectedStyle, toolInsertPoint);

  var hoverStyle = selectedStyle.cloneNode(true);
  hoverStyle.removeAttribute('id');
  hoverStyle.setAttribute('data-name', 'xuantingyangshi');
  hoverStyle.classList.remove('ps-tool-selection-style');
  hoverStyle.classList.add('ps-tool-hover-style');
  toolbar.insertBefore(hoverStyle, selectedStyle);

  var base = { x: 2.14, y: 45.67, width: 28.04, height: 21.76 };

  var excludedNames = {
    zuocebeijse: true,
    qianjingse: true,
    beijingse: true,
    qiehuan: true,
    morenqianjingse: true,
    xuanzhongtuozhuai: true,
    dingbuanniu: true,
    xaunzhongyangshi: true,
    xuantingyangshi: true
  };

  function directToolGroups() {
    return Array.prototype.filter.call(toolbar.children, function (child) {
      var name = child.getAttribute && child.getAttribute('data-name');
      return child.tagName && child.tagName.toLowerCase() === 'g' && name && !excludedNames[name];
    });
  }

  function ignoredCornerMarker(elementBox, toolBox) {
    return elementBox.width <= 3.6 &&
      elementBox.height <= 3.6 &&
      elementBox.x >= toolBox.x + toolBox.width * .62 &&
      elementBox.y >= toolBox.y + toolBox.height * .62;
  }

  function unionBox(boxes) {
    var minX = Math.min.apply(null, boxes.map(function (box) { return box.x; }));
    var minY = Math.min.apply(null, boxes.map(function (box) { return box.y; }));
    var maxX = Math.max.apply(null, boxes.map(function (box) { return box.x + box.width; }));
    var maxY = Math.max.apply(null, boxes.map(function (box) { return box.y + box.height; }));
    return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
  }

  function visualBox(tool) {
    var toolBox = tool.getBBox();
    var graphicElements = Array.prototype.filter.call(tool.querySelectorAll('path, rect, circle, ellipse, polygon, polyline, line'), function (element) {
      if (element.classList.contains('ps-tool-hit')) return false;

      var elementBox = element.getBBox();
      return !ignoredCornerMarker(elementBox, toolBox);
    });
    var boxes = graphicElements.map(function (element) {
      return element.getBBox();
    });

    return boxes.length ? unionBox(boxes) : toolBox;
  }

  function centeredPosition(tool) {
    var box = visualBox(tool);
    return [
      Math.round((box.x + box.width / 2 - base.width / 2) * 100) / 100,
      Math.round((box.y + box.height / 2 - base.height / 2) * 100) / 100
    ];
  }

  function toolPosition(tool) {
    return centeredPosition(tool);
  }

  function moveStyle(styleGroup, position) {
    var dx = Math.round((position[0] - base.x) * 100) / 100;
    var dy = Math.round((position[1] - base.y) * 100) / 100;
    styleGroup.setAttribute('transform', 'translate(' + dx + ' ' + dy + ')');
  }

  function addInteraction(toolSet, activeStyle, activeHoverStyle, initialTool) {
    var selectedTool = initialTool;
    moveStyle(activeStyle, toolPosition(selectedTool));

    toolSet.forEach(function (tool) {
      var name = tool.getAttribute('data-name');
      var position = toolPosition(tool);
      var hit = document.createElementNS(svgNS, 'rect');
      hit.setAttribute('class', 'ps-tool-hit');
      hit.setAttribute('x', position[0]);
      hit.setAttribute('y', position[1]);
      hit.setAttribute('width', base.width);
      hit.setAttribute('height', base.height);
      hit.setAttribute('rx', '1.5');
      hit.setAttribute('ry', '1.5');
      tool.insertBefore(hit, tool.firstChild);

      tool.setAttribute('data-ps-tool', 'true');
      tool.setAttribute('aria-label', name);

      tool.addEventListener('mouseenter', function () {
        if (tool === selectedTool) return;
        moveStyle(activeHoverStyle, position);
        activeHoverStyle.classList.add('is-visible');
      });

      tool.addEventListener('mouseleave', function () {
        activeHoverStyle.classList.remove('is-visible');
      });

      tool.addEventListener('click', function () {
        selectedTool = tool;
        activeHoverStyle.classList.remove('is-visible');
        moveStyle(activeStyle, position);
      });
    });
  }

  addInteraction(directToolGroups(), selectedStyle, hoverStyle, firstTool);

  var rightPanel = (svg || document).querySelector('[data-name="youcegongjv"]');
  if (rightPanel) {
    var rightNames = ['tuceng', 'wenben', 'duanluo', 'xiangxi'];
    var rightTools = rightNames.map(function (name) {
      return rightPanel.querySelector('[data-name="' + name + '"]');
    }).filter(Boolean);

    if (rightTools.length) {
      var rightSelectedStyle = selectedStyle.cloneNode(true);
      rightSelectedStyle.removeAttribute('id');
      rightSelectedStyle.removeAttribute('transform');
      rightSelectedStyle.setAttribute('data-name', 'youce-xuanzhongyangshi');
      rightSelectedStyle.classList.add('ps-tool-selection-style');

      var rightHoverStyle = rightSelectedStyle.cloneNode(true);
      rightHoverStyle.setAttribute('data-name', 'youce-xuantingyangshi');
      rightHoverStyle.classList.remove('ps-tool-selection-style');
      rightHoverStyle.classList.add('ps-tool-hover-style');

      rightPanel.insertBefore(rightSelectedStyle, rightTools[0]);
      rightPanel.insertBefore(rightHoverStyle, rightSelectedStyle);
      addInteraction(rightTools, rightSelectedStyle, rightHoverStyle, rightTools[0]);
    }
  }
})();
